styles:
/* ==================================================
   ポテンツァ3院比較表
   コンパクト版
   横スクロールなし・縦スクロールのみ
================================================== */

.potenza-compare-wrap {
    width: 100% !important;
    max-width: 100% !important;
    margin: 14px 0 !important;
    padding: 0 !important;
    box-sizing: border-box !important;
    font-family:
        "Yu Gothic",
        "Hiragino Kaku Gothic ProN",
        Meiryo,
        sans-serif !important;
}


/* ==================================================
   スクロールエリア
================================================== */

.potenza-table-scroll {
    width: 100% !important;
    max-width: 100% !important;

    /* この高さを超えると縦スクロール */
    max-height: 420px !important;

    /* 横スクロールなし */
    overflow-x: hidden !important;
    overflow-y: auto !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #fff !important;

    border: 1px solid #d5d5d5 !important;
    border-radius: 5px !important;

    box-sizing: border-box !important;
}


/* ==================================================
   テーブル本体
================================================== */

table.potenza-table {
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    border-collapse: separate !important;
    border-spacing: 0 !important;

    table-layout: fixed !important;

    background: #fff !important;

    color: #333 !important;

    font-size: 12px !important;
    line-height: 1.35 !important;
}


/* ==================================================
   列幅
================================================== */

/* 左の比較項目 */
table.potenza-table th:first-child {
    width: 15% !important;
}

/* 3クリニック */
table.potenza-table th:nth-child(2),
table.potenza-table td:nth-child(2),
table.potenza-table th:nth-child(3),
table.potenza-table td:nth-child(3),
table.potenza-table th:nth-child(4),
table.potenza-table td:nth-child(4) {
    width: 28.33% !important;
}


/* ==================================================
   全セル
================================================== */

table.potenza-table th,
table.potenza-table td {
    margin: 0 !important;

    /* 全体をコンパクトに */
    padding: 6px 4px !important;

    border: 0 !important;
    border-right: 1px solid #dedede !important;
    border-bottom: 1px solid #dedede !important;

    background: #fff !important;

    color: #333 !important;

    text-align: center !important;
    vertical-align: middle !important;

    font-size: 12px !important;
    line-height: 1.35 !important;

    word-break: break-word !important;
    overflow-wrap: anywhere !important;

    box-sizing: border-box !important;
}


/* 右端の余計な線を削除 */
table.potenza-table tr > *:last-child {
    border-right: 0 !important;
}


/* ==================================================
   1行目固定
================================================== */

table.potenza-table thead th {
    position: sticky !important;
    top: 0 !important;
    z-index: 20 !important;

    background: #f8e8ed !important;

    color: #333 !important;

    /* 固定ヘッダーを低くする */
    padding: 5px 3px !important;

    border-bottom: 2px solid #b75062 !important;

    text-align: center !important;
    vertical-align: middle !important;

    font-weight: 700 !important;

    box-shadow: 0 1px 3px rgba(0,0,0,.06) !important;
}


/* 左上 */
table.potenza-table thead th.potenza-item-head {
    background: #9f2936 !important;
    color: #fff !important;

    font-size: 10px !important;
}


/* ==================================================
   ヘッダー上部
   ＼○○を重視／
================================================== */

.potenza-target {
    display: block !important;

    margin: 0 0 2px !important;
    padding: 0 !important;

    color: #a8324b !important;

    font-size: 10px !important;
    font-weight: 700 !important;
    line-height: 1.1 !important;

    /* 必ず1行 */
    white-space: nowrap !important;

    letter-spacing: -0.2px !important;
}


/* ==================================================
   クリニック名
================================================== */

.potenza-clinic-name {
    display: block !important;

    margin: 0 0 3px !important;
    padding: 0 !important;

    color: #333 !important;

    font-size: 12px !important;
    font-weight: 700 !important;
    line-height: 1.2 !important;
}


/* ==================================================
   詳細はこちら
================================================== */

table.potenza-table a.potenza-btn {
    display: inline-block !important;

    width: auto !important;
    min-width: 0 !important;

    margin: 0 auto !important;
    padding: 3px 8px !important;

    background: #c6405d !important;
    color: #fff !important;

    border: 0 !important;
    border-radius: 3px !important;

    text-decoration: none !important;

    font-size: 10px !important;
    font-weight: 700 !important;
    line-height: 1.2 !important;

    white-space: nowrap !important;

    box-shadow: none !important;

    box-sizing: border-box !important;
}

table.potenza-table a.potenza-btn:hover {
    background: #ae344d !important;
    color: #fff !important;
}


/* ==================================================
   左側 比較項目
================================================== */

table.potenza-table tbody th.potenza-item-head {
    background: #f1f1f1 !important;

    color: #333 !important;

    font-size: 10px !important;
    font-weight: 700 !important;

    text-align: center !important;

    padding: 5px 2px !important;

    border-right: 1px solid #ccc !important;

    line-height: 1.25 !important;
}


/* ==================================================
   料金
   改行しても行間をほぼなくす
================================================== */

table.potenza-table tr.potenza-price-row th,
table.potenza-table tr.potenza-price-row td {
    padding-top: 4px !important;
    padding-bottom: 4px !important;
}


/* 1料金ごとのブロック */
.potenza-price-line {
    display: block !important;

    margin: 0 !important;
    padding: 0 !important;

    text-align: center !important;

    font-size: 10px !important;

    /* 折り返し時の行間を詰める */
    line-height: 1.05 !important;
}


/* 料金同士だけほんの少し間隔 */
.potenza-price-line + .potenza-price-line {
    margin-top: 2px !important;
}


/* 施術名 */
.potenza-price-line strong {
    display: inline !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #333 !important;

    font-size: 10px !important;
    font-weight: 700 !important;

    line-height: 1.05 !important;
}


/* 金額 */
.potenza-price-line span {
    display: inline !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #c52e50 !important;

    font-size: 10px !important;
    font-weight: 700 !important;

    line-height: 1.05 !important;
}


/* ==================================================
   おすすめポイント
================================================== */

.potenza-point {
    font-size: 10px !important;
    font-weight: 700 !important;

    line-height: 1.3 !important;
}


/* ==================================================
   背景色
================================================== */

table.potenza-table tbody tr:nth-child(odd) td {
    background: #fff !important;
}

table.potenza-table tbody tr:nth-child(even) td {
    background: #fafafa !important;
}

table.potenza-table tbody tr:nth-child(odd) th.potenza-item-head {
    background: #f2f2f2 !important;
}

table.potenza-table tbody tr:nth-child(even) th.potenza-item-head {
    background: #eaeaea !important;
}


/* ==================================================
   住所
================================================== */

.potenza-address {
    font-size: 9px !important;
    line-height: 1.3 !important;
}


/* ==================================================
   スマホ
================================================== */

@media screen and (max-width: 768px) {

    .potenza-compare-wrap {
        margin: 10px 0 !important;
    }

    .potenza-table-scroll {
        width: 100% !important;
        max-width: 100% !important;

        max-height: 400px !important;

        overflow-x: hidden !important;
        overflow-y: auto !important;
    }


    /* ==================================================
       列幅
    ================================================== */

    /* 左項目 */
    table.potenza-table th:first-child {
        width: 17% !important;
    }

    /* 3院 */
    table.potenza-table th:nth-child(2),
    table.potenza-table td:nth-child(2),
    table.potenza-table th:nth-child(3),
    table.potenza-table td:nth-child(3),
    table.potenza-table th:nth-child(4),
    table.potenza-table td:nth-child(4) {
        width: 27.66% !important;
    }


    /* ==================================================
       セル
    ================================================== */

    table.potenza-table th,
    table.potenza-table td {
        padding: 4px 2px !important;

        font-size: 9px !important;
        line-height: 1.25 !important;
    }


    /* ==================================================
       固定ヘッダー
    ================================================== */

    table.potenza-table thead th {
        padding: 4px 1px !important;
    }

    table.potenza-table thead th.potenza-item-head {
        font-size: 8px !important;
    }


    /* ==================================================
       ＼○○を重視／
       スマホでも1行固定
    ================================================== */

    .potenza-target {
        margin-bottom: 2px !important;

        font-size: 8px !important;
        line-height: 1 !important;

        white-space: nowrap !important;

        letter-spacing: -0.5px !important;
    }


    /* ==================================================
       クリニック名
    ================================================== */

    .potenza-clinic-name {
        margin-bottom: 2px !important;

        font-size: 9px !important;
        line-height: 1.15 !important;
    }


    /* ==================================================
       ボタン
    ================================================== */

    table.potenza-table a.potenza-btn {
        padding: 2px 5px !important;

        font-size: 8px !important;
        line-height: 1.15 !important;
    }


    /* ==================================================
       左側
    ================================================== */

    table.potenza-table tbody th.potenza-item-head {
        padding: 4px 1px !important;

        font-size: 8px !important;
        line-height: 1.2 !important;
    }


    /* ==================================================
       料金
    ================================================== */

    table.potenza-table tr.potenza-price-row th,
    table.potenza-table tr.potenza-price-row td {
        padding-top: 3px !important;
        padding-bottom: 3px !important;
    }

    .potenza-price-line {
        font-size: 8.5px !important;
        line-height: 1 !important;
    }

    .potenza-price-line strong,
    .potenza-price-line span {
        font-size: 8.5px !important;
        line-height: 1 !important;
    }

    .potenza-price-line + .potenza-price-line {
        margin-top: 1px !important;
    }


    /* ==================================================
       おすすめポイント
    ================================================== */

    .potenza-point {
        font-size: 8.5px !important;
        line-height: 1.2 !important;
    }


    /* ==================================================
       住所
    ================================================== */

    .potenza-address {
        font-size: 8px !important;
        line-height: 1.2 !important;
    }
}
